package dev.kelmagic.client;
import dev.kelmagic.research.ResearchState;import net.minecraft.client.Minecraft;
public final class ResearchClient {public static ResearchState state=ResearchState.EMPTY;public static void accept(dev.kelmagic.network.ResearchSnapshot p){state=p.state();dev.kelmagic.research.Research.CLIENT_VIEW=state;if(Minecraft.getInstance().screen instanceof CodexScreen c)c.researchChanged();else if(Minecraft.getInstance().screen instanceof ResearchEntryScreen c)c.researchChanged();}public static void notice(dev.kelmagic.network.ResearchNotice p){var n=dev.kelmagic.research.ResearchCatalog.BY_ID.get(p.id());if(n!=null)net.minecraft.client.gui.components.toasts.SystemToast.add(Minecraft.getInstance().getToasts(),net.minecraft.client.gui.components.toasts.SystemToast.SystemToastId.PERIODIC_NOTIFICATION,net.minecraft.network.chat.Component.literal("Открытие Кэл"),net.minecraft.network.chat.Component.literal(dev.kelmagic.research.Research.name(n)));}private ResearchClient(){}}
